import {constructionArt,professorElon} from './construction.js';
import {techArt,professorMike} from './hq-tech.js';
// New names are original fictional instructors; portraits are schematic placeholders.
const subject=(name,specialty,intro,activity,second,skin,coat,hair)=>({name,specialty,intro,activity,second,skin,coat,hair});
export const professors={
 elon:{...subject(professorElon.name,'Engineering and rockets',professorElon.intro,{label:'Build and test a machine',system:'construction',page:'projects'},{label:'Rocket Lab',system:'rocket',page:'home'},'#d1aa87','#d8e5db','#60717d'),established:true},
 mike:{...subject(professorMike.name,'Computing and robotics',professorMike.intro,{label:'Program a robot route',system:'tech',page:'sequence'},{label:'Robot sensors',system:'tech',page:'sensors'},'#c39b78','#d2dfeb','#635c59'),established:true},
 petra:subject('Professor Petra Vale','Geology and paleontology','Rocks hold clues. Let’s look at one layer, then ask what it can tell us.',{label:'Earth layers',system:'dig',page:'layers'},{label:'Caves and groundwater',system:'dig',page:'groundwater'},'#bd8c69','#c9d8c8','#5d514b'),
 leena:subject('Professor Leena Rao','Botany and growing food','A tiny seed can begin a big discovery. Let’s change one growing condition and observe.',{label:'Leaves and light',system:'farm',page:'leaf'},{label:'Hydroponic growing',system:'farm',page:'hydro'},'#9c6d50','#d4debb','#343b45'),
 marina:subject('Professor Marina Okafor','Oceanography and marine biology','There is a whole world under the surface. Let’s compare the water and the creatures that live there.',{label:'Underwater pressure',system:'aquatic',page:'pressure'},{label:'Ocean depth zones',system:'aquatic',page:'depth'},'#805c46','#bcd6df','#354752'),
 aya:subject('Professor Aya Mori','Flight and the atmosphere','Try a design, watch it move, then try one change. PIP can help us see what air does.',{label:'Rotors and air',system:'tech',page:'drone'},{label:'Thrust and payload',system:'rocket',page:'demo'},'#d2a68b','#c8d7e4','#3f414e'),
 farah:subject('Professor Farah Noor','Electricity and magnetism','Some forces work without touching. Let’s switch a coil on and see what changes.',{label:'Switchable electromagnet',system:'magnet',page:'coil'},{label:'Magnet and coil generator',system:'magnet',page:'generator'},'#ad815f','#d7d2e4','#4c4b56'),
 iris:subject('Professor Iris Vega','Light, optics and crystals','Follow the light. A clear crystal can help us ask questions about shape and materials.',{label:'Investigate quartz',system:'analysis',page:'quartz'},{label:'Look inside a leaf',system:'farm',page:'leaf'},'#ca9d80','#d6d4e6','#815f5b'),
 nia:subject('Professor Nia Laurent','Biology and xenobiology','Look closely at a living cell. On other worlds, we ask about conditions and evidence, not assume life is there.',{label:'Plant-cell model',system:'piptool',page:'life-lens'},{label:'Conditions for life',system:'piptool',page:'xeno-lab'},'#936d56','#cbdccf','#383b4a'),
 rowan:subject('Professor Rowan Silva','Ecosystems and the environment','A habitat is full of connections. Let’s follow one link between a plant, water and an animal.',{label:'Plants and pollinators',system:'piptool',page:'eco-probe'},{label:'Water recycling',system:'farm',page:'recycle'},'#b78c6d','#c1d4bb','#6c6055'),
 ada:subject('Professor Ada North','Mathematics and patterns','A pattern is something we can investigate. Let’s repeat a shape, count a group and look for symmetry.',{label:'Patterns and symmetry',system:'piptool',page:'pattern-projector'},{label:'Binary number lights',system:'tech',page:'binary'},'#d6b39b','#d3c9e2','#76675e'),
 mei:subject('Professor Mei Solano','Astronomy and astrophysics','What can light tell us about a distant world? Let’s begin with one thing we can observe in our sky.',{label:'Observe the sky',system:'rocket',page:'sky'},{label:'Choose an observing mission',system:'rocket',page:'missions'},'#c99e7e','#c7d2e4','#3d414e')
};
export function zoneProfessor(zone,expedition=null){if(expedition?.colony)return expedition.colony.kind==='home'?'leena':'mei';if(expedition?.active)return {sky:'aya',ocean:'marina',cave:'petra',forest:'rowan',farm:'leena'}[expedition.active]||'elon';return {grounds:'elon',hq:'elon',engineering:'elon',machineyard:'elon',rocketlab:'elon',coding:'mike',robotics:'mike',magnetism:'farah',flight:'aya',forest:'rowan',dig:'petra',diglands:'petra',farm:'leena',aquatic:'marina',chapterEarth:'petra',chapterMoon:'mei',elevator:'elon'}[zone]||'elon';}
export function professorView(id='elon',route='home'){const p=professors[id]||professors.elon,go=(label,route)=>({label,type:'page',route}),act=a=>({label:'▶ '+a.label,type:'activity',activity:a}),back=go('← '+p.name,'home');if(route.startsWith('directory')){const n=Math.max(0,parseInt(route.split(':')[1])||0),ids=Object.keys(professors);return {title:'Meet our science professors',text:'Choose an instructor. Each introduces a subject; PIP stays your active helper.',actions:[...ids.slice(n*3,n*3+3).map(id=>({label:professors[id].name+' / '+professors[id].specialty,type:'professor',id})),n?go('← Previous professors','directory:'+(n-1)):back,...(ids.length>(n+1)*3?[go('More professors →','directory:'+(n+1))]:[])],portrait:id};}
 if(route==='help')return {title:'PIP / One science step',text:'PIP: “Let’s try '+p.activity.label.toLowerCase()+'. We can change one choice, look at the result and repeat. There is no hurry.”',actions:[act(p.activity),go('🔊 Repeat the directions','repeat'),back,go('🧑‍🔬 Meet the team','directory:0')],portrait:id};
 return {title:p.name,text:p.specialty+'. '+p.intro+' PIP stays beside you to help with each step.',actions:[act(p.activity),act(p.second),go('🤖 PIP, show the next step','help'),go('🧑‍🔬 Meet the other professors','directory:0')],portrait:id};}
export function professorPortrait(id){if(id==='elon')return constructionArt('professor');if(id==='mike')return techArt('mike');const p=professors[id]||professors.petra;return `<svg xmlns="http://www.w3.org/2000/svg" width="240" height="180" viewBox="0 0 240 180"><rect width="240" height="180" rx="18" fill="${p.coat}"/><path d="M42 176v-45q0-30 78-30t78 30v45" fill="#fffbed" stroke="#17384a" stroke-width="4"/><path d="M99 105l21 33 21-33m-21 33v38" fill="none" stroke="#9badb7" stroke-width="4"/><path d="M83 48q0-34 37-34t37 34v23q0 35-37 35T83 71z" fill="${p.skin}"/><path d="M82 55V38q6-32 39-29 39 0 39 46l-19-23q-33 7-59 23z" fill="${p.hair}"/><g stroke="#17384a" stroke-width="3" fill="none"><rect x="89" y="51" width="24" height="19" rx="5"/><rect x="127" y="51" width="24" height="19" rx="5"/><path d="M113 59h14m-20 24q13 12 26 0"/></g><rect x="160" y="130" width="22" height="26" rx="4" fill="${p.coat}" stroke="#17384a" stroke-width="2"/><path d="M166 137h10m-10 7h10" stroke="#35bcb8" stroke-width="3"/></svg>`;}
